func TestParseBytes_TemplatesDirAndManPageName_Strict(t *testing.T) {
	tempDir := t.TempDir()
	os.MkdirAll(filepath.Join(tempDir, "templates"), 0755)
	os.MkdirAll(filepath.Join(tempDir, "dist"), 0755)
	os.WriteFile(filepath.Join(tempDir, "dist", "app"), []byte("#!/bin/sh\n"), 0755)
	os.WriteFile(filepath.Join(tempDir, "manual.1.md"), []byte("# NAME\napp - tool\n"), 0644)

	yamlData := []byte(`
name: myapp
description: Application description text
maintainer: Developer <dev@example.org>
homepage: https://example.org
license: MIT
command: myapp
payload_dir: dist
entrypoint: app
templates_dir: templates
man_pages:
  - source: manual.1.md
    section: 1
    name: custom-manual
targets:
  deb:
    section: utils
`)

	res, err := ParseBytes(yamlData, ParseOptions{
		WorkspaceDir:   tempDir,
		CheckWorkspace: true,
		Strict:         true,
	})
	if err != nil {
		t.Fatalf("expected successful strict parse, got error: %v", err)
	}
	if res.Config.TemplatesDir != "templates" {
		t.Errorf("expected TemplatesDir 'templates', got %q", res.Config.TemplatesDir)
	}
	if len(res.Config.ManPages) != 1 || res.Config.ManPages[0].Name != "custom-manual" {
		t.Errorf("expected ManPages[0].Name 'custom-manual', got %v", res.Config.ManPages)
	}
}

func TestValidate_ExtendedDescription(t *testing.T) {
	baseCfg := func() *CraftpackConfig {
		return &CraftpackConfig{
			Name:        "myapp",
			Description: "Valid description for the application",
			Maintainer:  "Dev <dev@example.com>",
			Homepage:    "https://example.com",
			License:     "MIT",
			Command:     "myapp",
			PayloadDir:  "dist",
			Entrypoint:  "bin",
			Targets:     TargetConfigs{Deb: &DebianTargetConfig{}},
		}
	}

	v := NewValidator("", false)

	// Valid multi-line extended description
	cfg1 := baseCfg()
	cfg1.ExtendedDescription = "This is a detailed paragraph.\n\nIt spans multiple lines.\nAnd even more details."
	errs := v.Validate(cfg1)
	for _, e := range errs {
		if e.Field == "extended_description" {
			t.Errorf("unexpected error on valid extended_description: %v", e)
		}
	}

	// Boundary condition: exactly 10,000 characters must pass
	cfgExact := baseCfg()
	cfgExact.ExtendedDescription = strings.Repeat("x", 10000)
	errsExact := v.Validate(cfgExact)
	for _, e := range errsExact {
		if e.Field == "extended_description" {
			t.Errorf("unexpected error on exactly 10000 chars extended_description: %v", e)
		}
	}

	// Boundary condition: 10,001 characters must fail
	cfg2 := baseCfg()
	cfg2.ExtendedDescription = strings.Repeat("A", 10001)
	errs2 := v.Validate(cfg2)
	foundLong := false
	for _, e := range errs2 {
		if e.Field == "extended_description" {
			foundLong = true
			expectedMsg := "extended_description exceeds maximum length of 10000 characters"
			if e.Message != expectedMsg {
				t.Errorf("expected message %q, got %q", expectedMsg, e.Message)
			}
		}
	}
	if !foundLong {
		t.Error("expected error for extended_description > 10000 chars")
	}

	// Allowed control characters (\t, \n, \r) must pass
	cfgWhitespace := baseCfg()
	cfgWhitespace.ExtendedDescription = "First line\r\n\tIndented with tab\nAnother line"
	errsWS := v.Validate(cfgWhitespace)
	for _, e := range errsWS {
		if e.Field == "extended_description" {
			t.Errorf("unexpected error on valid whitespace (tabs/newlines/CR): %v", e)
		}
	}

	// Contains invalid control char (e.g. \x07 bell, \x00 NUL)
	cfg3 := baseCfg()
	cfg3.ExtendedDescription = "Bad\x07char"
	errs3 := v.Validate(cfg3)
	foundCtrl := false
	for _, e := range errs3 {
		if e.Field == "extended_description" {
			foundCtrl = true
		}
	}
	if !foundCtrl {
		t.Error("expected error for control character in extended_description")
	}

	// Empty string must pass without error
	cfgEmpty := baseCfg()
	cfgEmpty.ExtendedDescription = ""
	errsEmpty := v.Validate(cfgEmpty)
	for _, e := range errsEmpty {
		if e.Field == "extended_description" {
			t.Errorf("unexpected error on empty extended_description: %v", e)
		}
	}
}

func TestValidate_Changelog(t *testing.T) {
	tempDir := t.TempDir()
	changelogFile := filepath.Join(tempDir, "CHANGELOG.md")
	os.WriteFile(changelogFile, []byte("changelog content"), 0644)

	baseCfg := func() *CraftpackConfig {
		return &CraftpackConfig{
			Name:        "myapp",
			Description: "Valid description for the application",
			Maintainer:  "Dev <dev@example.com>",
			Homepage:    "https://example.com",
			License:     "MIT",
			Command:     "myapp",
			PayloadDir:  "dist",
			Entrypoint:  "bin",
			Targets:     TargetConfigs{Deb: &DebianTargetConfig{}},
		}
	}

	v := NewValidator(tempDir, false)

	// Valid keywords
	for _, kw := range []string{"auto", "none", "false", "disabled"} {
		cfg := baseCfg()
		cfg.Changelog = kw
		errs := v.Validate(cfg)
		for _, e := range errs {
			if e.Field == "changelog" {
				t.Errorf("unexpected error for changelog %q: %v", kw, e)
			}
		}
	}

	// Valid relative path to existing file
	cfgValidFile := baseCfg()
	cfgValidFile.Changelog = "CHANGELOG.md"
	errs := v.Validate(cfgValidFile)
	for _, e := range errs {
		if e.Field == "changelog" {
			t.Errorf("unexpected error for existing changelog file: %v", e)
		}
	}

	// Non-existent file
	cfgMissingFile := baseCfg()
	cfgMissingFile.Changelog = "NONEXISTENT.md"
	errsMissing := v.Validate(cfgMissingFile)
	foundMissing := false
	for _, e := range errsMissing {
		if e.Field == "changelog" {
			foundMissing = true
		}
	}
	if !foundMissing {
		t.Error("expected error for non-existent changelog file")
	}

	// Escaping path
	cfgEscape := baseCfg()
	cfgEscape.Changelog = "../outside.md"
	errsEscape := v.Validate(cfgEscape)
	foundEscape := false
	for _, e := range errsEscape {
		if e.Field == "changelog" {
			foundEscape = true
		}
	}
	if !foundEscape {
		t.Error("expected error for escaping changelog path")
	}
}
